import { Effect, Schema } from "effect";
import { useState } from "react";
import { Form, useAppForm } from "@/registry/erbium/ui/form";

const Email = Schema.String.check(
  Schema.isPattern(/^[^\s@]+@[^\s@]+\.[^\s@]+$/u, { message: "Enter a valid email address." }),
);

const OptionalEmail = Schema.Union([Schema.Literal(""), Email]);

const emailForm = (email: typeof Email | typeof OptionalEmail) =>
  Schema.toStandardSchemaV1(Schema.Struct({ email }));

const RequiredEmailForm = emailForm(Email);
const OptionalEmailForm = emailForm(OptionalEmail);

const FormDemo = ({
  defaultEmail = "",
  required = true,
  submitLabel = "Submit",
}: {
  defaultEmail?: string;
  required?: boolean;
  submitLabel?: string;
}) => {
  const [submitted, setSubmitted] = useState("");

  const form = useAppForm({
    defaultValues: { email: defaultEmail },
    onSubmit: async ({ value }) => {
      // Stands in for the request that sends the form.
      await Effect.runPromise(Effect.sleep("450 millis"));
      setSubmitted(value.email);
    },
    validators: { onDynamic: required ? RequiredEmailForm : OptionalEmailForm },
  });

  return (
    <Form form={form} className="w-80 space-y-4">
      <form.AppField name="email">
        {(field) => (
          <field.TextField
            label="Email"
            type="email"
            autoComplete="email"
            description="We will use this to contact you."
          />
        )}
      </form.AppField>
      <form.SubmitButton successLabel="Submitted">{submitLabel}</form.SubmitButton>
      {submitted ? <output className="block">Submitted: {submitted}</output> : null}
    </Form>
  );
};

export default FormDemo;

import { Effect, Schema } from "effect";
import { useState } from "react";
import { FieldGroup } from "@/registry/erbium/ui/field";
import { Form, useAppForm } from "@/registry/erbium/ui/form";

/** One schema validates the form in the browser and the request on the server. */
const ContactRequest = Schema.Struct({
  email: Schema.String.check(
    Schema.isPattern(/^[^\s@]+@[^\s@]+\.[^\s@]+$/u, { message: "Enter a valid email address." }),
  ),
  message: Schema.String.check(
    Schema.isMinLength(20, { message: "Write at least 20 characters so we can help." }),
  ),
  name: Schema.Trim.check(Schema.isNonEmpty({ message: "Enter your name." })),
  terms: Schema.Literal(true).annotate({ message: "Accept the terms to continue." }),
  updates: Schema.Boolean,
});

const defaultValues = {
  email: "",
  message: "",
  name: "",
  terms: false,
  updates: true,
};

const FormValidation = () => {
  const [sent, setSent] = useState("");

  const form = useAppForm({
    defaultValues,
    onSubmit: async ({ value }) => {
      // The submitted values passed validation, so decoding applies the
      // schema's transformations, e.g. trimming the name.
      const contact = Schema.decodeUnknownSync(ContactRequest)(value);
      // Stands in for the request that sends the form.
      await Effect.runPromise(Effect.sleep("450 millis"));
      setSent(contact.name);
    },
    validators: { onDynamic: Schema.toStandardSchemaV1(ContactRequest) },
  });

  return (
    <Form form={form} className="w-full max-w-sm">
      <FieldGroup>
        <form.AppField name="name">
          {(field) => <field.TextField label="Name" autoComplete="name" />}
        </form.AppField>
        <form.AppField name="email">
          {(field) => <field.TextField label="Email" type="email" autoComplete="email" />}
        </form.AppField>
        <form.AppField name="message">
          {(field) => (
            <field.TextareaField
              label="Message"
              description="Tell us what you need help with."
              rows={4}
            />
          )}
        </form.AppField>
        <form.AppField name="updates">
          {(field) => (
            <field.SwitchField
              label="Product updates"
              description="A short email when something ships."
            />
          )}
        </form.AppField>
        <form.AppField name="terms">
          {(field) => <field.CheckboxField label="I accept the terms of service" />}
        </form.AppField>
        <form.SubmitButton successLabel="Sent">Send message</form.SubmitButton>
        {sent ? <output className="block">Thanks, {sent}. We will reply soon.</output> : null}
      </FieldGroup>
    </Form>
  );
};

export default FormValidation;

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import Demo from \"../examples/form-demo\";\n\nconst Example = (args: { defaultEmail: string; required: boolean; submitLabel: string }) => (\n  <Demo key={args.defaultEmail} {...args} />\n);\n\nexport default Example;\n";

import ValidationExample from "./variants/validation";

const ValidationSource = "import Demo from \"../examples/form-validation\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nImport `useForm` from `@tanstack/react-form`. Use `form.Field` for state and validation, then compose the visible control with `Field`, `FieldLabel`, `FieldDescription`, `FieldError`, and an input component. Keep `FieldError` mounted with `errors={field.state.meta.errors}` so validation messages expand smoothly, and connect the input with `aria-describedby`. Validate on blur or change as needed, set `noValidate` on the form, and call `form.handleSubmit()` after preventing the default submit. Use `onSubmitInvalid` to shake invalid controls on every rejected attempt while TanStack Form continues to own error state. See the [Shadcn/ui TanStack Form guide](https://ui.shadcn.com/docs/forms/tanstack-form) for the related upstream pattern.\n\n## External documentation\n\nTanStack Form manages form state, validation, and submission in these examples. TanStack Pacer handles debounced submission behavior.\n\n- [TanStack Form](https://tanstack.com/form/latest)\n- [TanStack Pacer](https://tanstack.com/pacer/latest)",
      },
    },
  },
  tags: ["autodocs"],
} satisfies Meta;

export default { ...meta, title: "Components/Form",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  defaultEmail: string;
  required: boolean;
  submitLabel: string;
}> = {
  argTypes: {
    defaultEmail: { control: "text" },
    required: { control: "boolean" },
    submitLabel: { control: "text" },
  },
  args: { defaultEmail: "", required: true, submitLabel: "Submit" },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Validation: Story = {
  parameters: {
    docs: {
      description: { story: "Validate a form field and display its error beside the control.\n\nCompose `FieldDescription` and `FieldError` together. The description is removed while the field is invalid and returns when validation clears, so helper information and errors never appear together." },
      source: { code: ValidationSource },
    },
  },
  render: ValidationExample,
};

import Demo from "../examples/form-demo";

const Example = (args: { defaultEmail: string; required: boolean; submitLabel: string }) => (
  <Demo key={args.defaultEmail} {...args} />
);

export default Example;

import Demo from "../examples/form-validation";

const Example = () => <Demo />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <OverlayProvider>
      {children}
      {toast && <Toaster />}
    </OverlayProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);
